"use strict";

jest.mock("aws-sdk", () => ({
  S3: jest.fn(() => ({})),
  KMS: jest.fn(() => ({})),
}));
jest.mock("../utils/http", () => ({
  sendRequest: jest.fn(),
  getToken: jest.fn(),
}));

const { Readable } = require("stream");
const { Response } = jest.requireActual("node-fetch");
const http = require("../utils/http");
const { processPayload } = require("../utils/request-processor");

const LARGE_BODY_BYTES = 128 * 1024;

const noopLogger = { debug: jest.fn(), info: jest.fn(), error: jest.fn() };

const fakeResponse = (text) => ({
  status: 200,
  statusText: "OK",
  text: jest.fn().mockResolvedValue(text),
  clone: jest.fn(() => {
    throw new Error("clone() leaves an unread branch that stalls large bodies");
  }),
});

const payloadOf = (payloadType) => ({
  payloadType,
  method: "POST",
  targetUrl: "https://receiver.example.test/hook",
  authentication: { type: "None" },
  payload: "{}",
});

const largeXmlSuccess = () =>
  `<xml><success>true</success><pad>${"a".repeat(LARGE_BODY_BYTES)}</pad></xml>`;

describe("processPayload response body handling", () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it("reads a large JSON response body directly without cloning", async () => {
    const response = fakeResponse("x".repeat(LARGE_BODY_BYTES));
    http.sendRequest.mockResolvedValue(response);

    await processPayload({ payload: payloadOf("JSON"), logger: noopLogger });

    expect(response.clone).not.toHaveBeenCalled();
    expect(response.text).toHaveBeenCalledTimes(1);
  });

  it("reads a large SOFTPRO_LEGACY_XML success response directly without cloning", async () => {
    const response = fakeResponse(largeXmlSuccess());
    http.sendRequest.mockResolvedValue(response);

    await processPayload({
      payload: payloadOf("SOFTPRO_LEGACY_XML"),
      logger: noopLogger,
    });

    expect(response.clone).not.toHaveBeenCalled();
    expect(response.text).toHaveBeenCalledTimes(1);
  });

  it("completes for a real node-fetch response streaming a large body", async () => {
    const chunk = Buffer.alloc(16 * 1024, "x");
    const chunks = Array.from({ length: 8 }, () => chunk);
    const response = new Response(Readable.from(chunks), { status: 200 });
    http.sendRequest.mockResolvedValue(response);

    await processPayload({ payload: payloadOf("JSON"), logger: noopLogger });

    expect(response.bodyUsed).toBe(true);
  }, 5000);

  it("still rejects a SOFTPRO_LEGACY_XML response that reports failure", async () => {
    const response = fakeResponse("<xml><success>false</success></xml>");
    http.sendRequest.mockResolvedValue(response);

    await expect(
      processPayload({
        payload: payloadOf("SOFTPRO_LEGACY_XML"),
        logger: noopLogger,
      })
    ).rejects.toThrow("returned bad response");
  });
});

describe("processPayload response logging", () => {
  const CAP = 256;
  const MARKER = "…";

  beforeEach(() => {
    jest.clearAllMocks();
  });

  const loggedEntry = () => noopLogger.info.mock.calls[0][0];

  it("logs a bounded excerpt ending with a marker for an oversized body", async () => {
    const body = "x".repeat(LARGE_BODY_BYTES);
    http.sendRequest.mockResolvedValue(fakeResponse(body));

    await processPayload({ payload: payloadOf("JSON"), logger: noopLogger });

    const { resp } = loggedEntry();
    expect(resp.length).toBeLessThanOrEqual(CAP + 1);
    expect(resp.endsWith(MARKER)).toBe(true);
    expect(resp.startsWith("x".repeat(CAP))).toBe(true);
  });

  it("logs the full byte length of the body alongside the excerpt", async () => {
    const body = "é".repeat(LARGE_BODY_BYTES);
    http.sendRequest.mockResolvedValue(fakeResponse(body));

    await processPayload({ payload: payloadOf("JSON"), logger: noopLogger });

    expect(loggedEntry().responseBytes).toBe(LARGE_BODY_BYTES * 2);
  });

  it("logs a short body unchanged", async () => {
    http.sendRequest.mockResolvedValue(fakeResponse("ok"));

    await processPayload({ payload: payloadOf("JSON"), logger: noopLogger });

    expect(loggedEntry().resp).toBe("ok");
    expect(loggedEntry().responseBytes).toBe(2);
  });

  it("keeps verb, url and code in the log entry", async () => {
    http.sendRequest.mockResolvedValue(fakeResponse("ok"));

    await processPayload({ payload: payloadOf("JSON"), logger: noopLogger });

    expect(loggedEntry()).toMatchObject({
      verb: "POST",
      url: "https://receiver.example.test/hook",
      code: 200,
    });
  });

  it("omits the full body from the bad XML response error message", async () => {
    const body = `<xml><success>false</success><pad>${"b".repeat(
      LARGE_BODY_BYTES
    )}</pad></xml>`;
    http.sendRequest.mockResolvedValue(fakeResponse(body));

    const failure = await processPayload({
      payload: payloadOf("SOFTPRO_LEGACY_XML"),
      logger: noopLogger,
    }).catch((err) => err);

    expect(failure.message).toContain("returned bad response");
    expect(failure.message).not.toContain(body);
    expect(failure.message.length).toBeLessThan(CAP + 200);
  });
});

