"use strict";

const aws = require("aws-sdk");
const xml2js = require("xml2js");
const crypto = require("crypto");
const path = require("path");
const http = require("./http");

const s3 = new aws.S3({ apiVersion: "2006-03-01" });
const kms = new aws.KMS();

exports.requestProcessor = async ({ bucketName, key, logger }) => {
  if (!key.toLowerCase().endsWith(".json")) {
    throw new Error(
      `The key of '${key}' is not a JSON file so it can NOT be processed. Skipping this item...`
    );
  }
  await processEvent({ bucketName, key, logger });
};

const processEvent = async ({ bucketName, key, logger }) => {
  // Get the payload to process
  const parsedKey = decodeURIComponent(key.replace(/\+/g, " "));
  const object = await getObject({ bucketName, key: parsedKey, logger });
  const payload = await getPayload({ object, key: parsedKey, logger });

  // Process the payload
  await processPayload({ payload: payload.payload, logger });
};

const decryptData = async ({ encryptionData, filename }) => {
  var kmsKeyBase64 = encryptionData.key;
  var ivBase64 = encryptionData.iv;
  var encryptionContext = { filename: filename };
  var algo = encryptionData.algo;
  switch (algo) {
    case "AES/CBC/PKCS7Padding":
      algo = "aes-256-cbc";
      break;
    default:
      throw new Error("Unsupported encryption algorithm: " + algo);
  }

  var kmsKeyBuffer = Buffer.from(kmsKeyBase64, "base64");
  let kmsData = await kms
    .decrypt({
      CiphertextBlob: kmsKeyBuffer,
      EncryptionContext: encryptionContext,
    })
    .promise();
  const decipher = crypto.createDecipheriv(
    algo,
    kmsData.Plaintext,
    Buffer.from(ivBase64, "base64")
  );
  var dec = decipher.update(encryptionData.encryptedJson, "base64", "utf8");
  dec += decipher.final("utf8");
  return JSON.parse(dec);
};

const getObject = async ({ bucketName, key, logger }) => {
  const params = {
    Bucket: bucketName,
    Key: key,
  };
  // Get the object to process
  logger.debug(`Getting the object: ${JSON.stringify(params)}`);
  const object = await s3.getObject(params).promise();
  logger.debug(
    `Done retrieving the object: ContentLength: ${object.ContentLength}, ContentType: ${object.ContentType}`
  );
  return object;
};

const getPayload = async ({ object, key, logger }) => {
  logger.debug("Parsing the payload...");
  let payload = JSON.parse(object.Body.toString("utf-8"));
  if (payload.hasOwnProperty("encryptionData")) {
    const filename = path.basename(key);
    logger.debug("Decrypting the payload...");
    const decryptedData = await decryptData({
      encryptionData: payload.encryptionData,
      filename,
    });
    // The decrypted data is an object which is allowed to overwrite/add
    // any fields to the plain text paylod, so merge them here
    payload = Object.assign({}, payload, decryptedData);
    logger.debug(`Done decrypting the payload`);
  }
  return {
    contentType: object.ContentType,
    contentLength: object.ContentLength,
    payload: payload,
  };
};

const RESPONSE_EXCERPT_CHARS = 256;
const TRUNCATION_MARKER = "…";

const responseExcerpt = (text) =>
  text.length > RESPONSE_EXCERPT_CHARS
    ? text.slice(0, RESPONSE_EXCERPT_CHARS) + TRUNCATION_MARKER
    : text;

const processPayload = async ({ payload, logger }) => {
  logger.debug("Processing the payload...");

  const payloadType = payload.hasOwnProperty("payloadType")
    ? payload.payloadType.toString()
    : "SOFTPRO_LEGACY_XML";

  let authorization =
    payload.authentication.type === "None"
      ? payload.authentication.type.toString()
      : `${payload.authentication.type} ${payload.authentication.config.basicAuthCredsBase64}`;

  if (payload.authentication.type === "Bearer") {
    logger.debug("Payload using Bearer auth type, requesting access token.");
    const accessToken = await http.getToken({
      idServer: payload.authentication.config.idServer,
      basicAuthCredsBase64: payload.authentication.config.basicAuthCredsBase64,
      scope: payload.authentication.config.scope,
      grantType: payload.authentication.config.grantType,
    });
    authorization = `Bearer ${accessToken}`;
    logger.debug("Payload using Bearer auth type, access token received.");
  }

  const contentType =
    payloadType === "JSON" ? "application/json" : "application/xml";

  const headers = {
    Authorization: authorization,
    "Content-Type": contentType,
  };

  const response = await http.sendRequest({
    url: encodeURI(payload.targetUrl),
    headers: headers,
    verb: payload.method,
    body: payload.payload,
    logger,
  });
  logger.debug(
    `Done processing the payload, Target Payload Response Status: ${response.status}, Response Status Text: ${response.statusText}`
  );

  const responseText = await response.text();
  logger.info({
    verb: payload.method,
    url: encodeURI(payload.targetUrl),
    code: response.status,
    resp: responseExcerpt(responseText),
    responseBytes: Buffer.byteLength(responseText),
  });

  if (payloadType === "SOFTPRO_LEGACY_XML") {
    const xmlBodyAsJson = await parseXMLBody(responseText);
    if (!(xmlBodyAsJson.xml.success && JSON.parse(xmlBodyAsJson.xml.success))) {
      throw new Error(
        `HTTP ${payload.method} to ${payload.targetUrl} returned bad response: ${responseExcerpt(responseText)}`
      );
    }
  }
};

exports.processPayload = processPayload;

const parseXMLBody = (bodyAsString) =>
  new Promise((resolve, reject) => {
    xml2js.parseString(
      bodyAsString,
      { explicitArray: false },
      (err, result) => {
        if (err) {
          return reject(err);
        }
        return resolve(result);
      }
    );
  });
